// The executor (tasks-dispatch DESIGN §6) — a pull worker over the queue. Each
// iteration: pick the next ready item, claim it by a verified lease, evaluate the
// precondition (THE only place it is ever evaluated), then on a go run prework and
// either converge (agentless) or hand off to an agent session; on a no-go roll a
// scheduled item to its next anchor with the reason on record.
//
// An executor's whole interface is issue read/write plus the repo at HEAD, which
// is what makes it platform-agnostic: the reference deployment is a job in the
// vendored workflows (the tick's post-tick drain, and a `labeled`-event run for
// latency), but a runner anywhere with an issues-scope token qualifies. Nothing
// enumerates executors; identity is self-declared in the claim comment.
//
// The pure decisions live at the top and test with fixtures; the shell below is
// the GitHub/prework/invocation I/O around them.

import { pathToFileURL } from 'node:url';
import { nextAnchor } from './anchors.mjs';
import {
  READY, URGENT, EXECUTING, AGENT, BLOCKED, NEEDS_HUMAN, ORIGIN_SCHEDULE,
  OUTCOME_DONE, OUTCOME_DELIVERED, OUTCOME_OBSOLETE, QUEUE_LABELS,
  CLAIM_MARKER, HANDOFF_MARKER, EPISODE_MARKER,
  parseWorkItemTitle, parseWorkItemBody, withNotBefore, withSection, hasLabel,
} from './work-item.mjs';

// How many items one executor run may take before it stops. Small on purpose: an
// executor is code iterating a queue, and more capacity is more executors, not a
// longer loop (DESIGN §10).
export const DEFAULT_MAX_ITEMS = 3;

const titleOf = (item) => (item.title ?? '').trim();
const taskIdOf = (item) => {
  const p = parseWorkItemTitle(item.title);
  return p ? `${p.pack}/${p.task}` : null;
};

// The pick order (DESIGN §6.1): urgent first, then oldest-created, with two skip
// rules read live at pick time.
//
//  - SAME-TITLE MUTEX (S15/F6): skip an item whose exact title has another open
//    item executing or handed to an agent — one task, one execution at a time,
//    while a fan-out's distinct qualifiers still parallelize.
//  - THE `after` YIELD (S24): skip a scheduled item whose task declares `after:
//    [T]` while T's standing item is live THIS CYCLE (ready / executing / agent).
//    A rolled upstream (blocked until its next anchor: it declined this cycle)
//    does not block, and neither does one sitting `needs-human` — a broken
//    upstream must not halt its dependents indefinitely. Deliberately NOT a
//    `Blocked-by` edge: a standing item that rolls never closes, so blocked-by
//    would starve every dependent of a quiet upstream forever.
//
// `open` is every open work item; `taskAfter(id)` gives a task's declared
// upstreams as `<pack>/<task>` ids.
export function pickOrder(open = [], { taskAfter = () => [] } = {}) {
  const live = (item) => hasLabel(item, READY) || hasLabel(item, EXECUTING) || hasLabel(item, AGENT);
  const liveUpstream = (upstreamId) => open.some((o) =>
    taskIdOf(o) === upstreamId && hasLabel(o, ORIGIN_SCHEDULE) && live(o));

  return open
    .filter((i) => hasLabel(i, READY) && !hasLabel(i, NEEDS_HUMAN))
    .filter((i) => !open.some((o) => o.number !== i.number && titleOf(o) === titleOf(i)
      && (hasLabel(o, EXECUTING) || hasLabel(o, AGENT))))
    .filter((i) => {
      if (!hasLabel(i, ORIGIN_SCHEDULE)) return true;
      return !taskAfter(taskIdOf(i)).some(liveUpstream);
    })
    .sort((a, b) =>
      (hasLabel(b, URGENT) ? 1 : 0) - (hasLabel(a, URGENT) ? 1 : 0)
      || new Date(a.created_at) - new Date(b.created_at)
      || a.number - b.number);
}

// The claim comment carries WHO and WHEN — the executor id and its run URL —
// because executor identity is an unbounded set and must never become a label
// (DESIGN §4).
export const claimComment = ({ executor, runUrl, at }) =>
  `${CLAIM_MARKER}\nClaimed by executor \`${executor}\` at ${at}.${runUrl ? `\n\nRun: ${runUrl}` : ''}`;

// Who won the claim, out of an item's comments (DESIGN §6.2). Three precisions,
// each an implicit assumption made explicit:
//
//  - "EARLIEST" MEANS LOWEST COMMENT ID, never timestamp. GitHub comment

// Agent invocation (tasks-dispatch DESIGN §12, §14.6). The executor starts the
// agent session with an API CALL rather than by arming a label event, which is
// what retires the re-arm, the grace window and the transport dance — and what
// makes a lost hand-off a synchronous, visible failure at the executor instead of
// a label event fired into the void.
//
// A TASK NAMES AN ENDPOINT, NEVER A URL. The declaration is vendored verbatim
// into every consuming repo, so it must never carry deployment detail or anything
// adjacent to a credential: `invocation_endpoint: 'fleet'` names a key, and the
// repo's own config maps that key to a URL and to the NAME of the repo Actions
// secret holding its token. That indirection is also what replaces the whole
// self/fleet apparatus — reach is a property of which endpoint you call, so a
// task needing wider access names a different endpoint and nothing else in the
// system needs a concept of scope.
//
// THE PROMPT NAMES ONE ITEM AND CARRIES NO INSTRUCTIONS. Everything
// behavior-defining is read by the session from the tracked task files at HEAD;
// the prompt says which issue and which nonce, and the session validates both in
// code before acting (DESIGN §7).

export const DEFAULT_ENDPOINT = 'default';

// The endpoint is a ROUTINE'S API TRIGGER — `POST /v1/claude_code/routines/
// <trigger-id>/fire` with a per-routine bearer token — which is what Claude Code
// on the web actually exposes to an HTTP caller. Three consequences the design's
// "a CCR API call" did not spell out, each verified against the routines docs
// rather than assumed:
//
//  - THE BEHAVIOR IS THE ROUTINE'S STORED PROMPT, not ours. `text` reaches the
//    session wrapped in a `<routine-fire-payload>` block explicitly labelled
//    untrusted, and a routine acts on it only because its own saved prompt says
//    to. That is the issue-is-data posture arriving for free at one more hop: our
//    payload names an item, and every instruction comes from a stored artifact.
//    The routine's stored prompt is one line pointing at `instructions.md` beside
//    this file, so the whole of what a session does is tracked and reviewed.
//  - THE BODY CARRIES ONE FIELD. `text` is freeform and unparsed — structured
//    JSON would arrive as a literal string — so the item number and nonce go in
//    as prose, and nothing else goes in at all.
//  - THERE IS NO IDEMPOTENCY KEY (standing entry 11, answered: the endpoint
//    offers none), which is exactly why THIS MODULE CALLS ONCE PER ITEM AND NEVER
//    RETRIES. A retry is only safe when you know the first call did nothing, and
//    a client-side timeout is the one case where you cannot know — the session
//    may well have started. Retrying there is what would make invocation
//    at-least-once and put two sessions on one item; declining to retry is what
//    keeps it at-most-once and lets the whole agent-side claim protocol delete.
//    An outcome we did not learn is reported as UNKNOWN and resolved by the agent
//    leash, which is a rule that already exists, rather than by a guess here.
//
// The beta header is dated and the endpoint is a research preview whose two most
// recent header versions keep working, so it lives in config with a default here
// — a rotation is then a config edit on one repo, never an engine release the
// whole fleet waits for.
export const DEFAULT_HEADERS = Object.freeze({
  'anthropic-beta': 'experimental-cc-routine-2026-04-01',
  'anthropic-version': '2023-06-01',
});

// The endpoint a task's hand-off calls, resolved against the repo's config.
// Returns `{ name, url, tokenEnv, headers }` or `{ name, error }` — a task naming
// an endpoint the repo has not configured is a repo-configuration fact, reported

